import numpy as np
from datetime import datetime

CLASSES = ["T-shirt", "Trouser", "Pullover", "Dress", "Coat",
           "Sandal", "Shirt", "Sneaker", "Bag", "Ankle boot"]


def softmax(z):
    e = np.exp(z - np.max(z))
    return e / e.sum()


def top_k_predictions(logits, class_names, k=3):
    probs = softmax(logits)
    best = np.argsort(probs)[::-1][:k]
    return [(class_names[i], float(probs[i])) for i in best]


def confusion_matrix(y_true, y_pred, num_classes):
    cm = np.zeros((num_classes, num_classes), dtype=int)
    for t, p in zip(y_true, y_pred):
        cm[t][p] += 1
    return cm


def version_name(model_name, when):
    return f"{model_name}_v{when:%Y%m%d_%H%M%S}.npz"


logits = np.array([0.1, 0.2, 2.5, 0.3, 1.9, -1.0, 1.2, -0.5, 0.0, -2.0])   # model output for one image
top3 = top_k_predictions(logits, CLASSES, k=3)
if top3 is not None:
    for name, confidence in top3:
        print(f"{name}: {confidence:.3f}")
print(confusion_matrix([0, 2, 2, 4, 4], [0, 2, 4, 4, 2], 5))
print(version_name("fashion_cnn", datetime(2026, 11, 3, 14, 25, 0)))
